package com.harshith.leave.controller; import com.harshith.leave.entity.LeaveRequest; import com.harshith.leave.service.LeaveService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/leaves") public class LeaveController {private final LeaveService s; public LeaveController(LeaveService s){this.s=s;} @PostMapping("/employee/{employeeId}") public LeaveRequest apply(@PathVariable Long employeeId,@Valid @RequestBody LeaveRequest r){return s.apply(employeeId,r);} @GetMapping public List<LeaveRequest> all(){return s.all();} @GetMapping("/{id}") public LeaveRequest get(@PathVariable Long id){return s.get(id);} @GetMapping("/employee/{employeeId}") public List<LeaveRequest> byEmployee(@PathVariable Long employeeId){return s.byEmployee(employeeId);} @PutMapping("/{id}/approve") public LeaveRequest approve(@PathVariable Long id){return s.approve(id);} @PutMapping("/{id}/reject") public LeaveRequest reject(@PathVariable Long id){return s.reject(id);} @PutMapping("/{id}/cancel") public LeaveRequest cancel(@PathVariable Long id){return s.cancel(id);} }